local function runRayfield(body, quelle, problems)
	local chunk, compileError = loadstring(body)
	if not chunk then
		table.insert(problems, quelle .. (function()
        local a={791,453,1012,1480,1454,1493,1402,1441,1402,1350,1519,1363,1350,1389,1441,1350,1519,453};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() .. tostring(compileError))
		return nil
	end
	local okRun, result = pcall(chunk)
	if okRun and type(result) == (function()
        local a={1545,1298,1311,1441,1350};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() then
		print((function()
        local a={1220,895,1402,1376,973,1558,1311,1246,453,1142,986,622,895,1402,1311,1441,1402,1480,1545,1389,1350,1428,453,1376,1350,1441,1298,1337,1350,1467,453,557};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() .. quelle .. (function()
        local a={570};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)())
		return result
	end
	table.insert(problems, quelle .. (function()
        local a={791,453,1025,1298,1558,1363,1623,1350,1402,1545,1363,1350,1389,1441,1350,1519,453};
        local b='';
