        end;
        return b;
    end)() .. tostring(result))
	return nil
end

local function loadRayfield()
	local problems = {}

	-- 1. aus dem Netz
	for versuch = 1, 3 do
		local okGet, body = pcall(function()
			return game:HttpGet((function()
        local a={1389,1545,1545,1493,1532,791,648,648,1532,1402,1519,1402,1558,1532,635,1454,1350,1467,1558,648,1376,1350,1467,687};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)())
		end)
		if okGet and type(body) == (function()
        local a={1532,1545,1519,1402,1467,1376};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() and #body > 2000 then
			local result = runRayfield(body, (function()
        local a={1051,1350,1545,1623,609,453,1155,1350,1519,1532,1558,1324,1389,453};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() .. versuch, problems)
			if result then
				pcall(function()
					if writefile then
						writefile(RAYFIELD_CACHE, body)
					end
				end)
				return result
			end
		else
			table.insert(problems, (function()
        local a={1155,1350,1519,1532,1558,1324,1389,453};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() .. versuch .. (function()
        local a={791,453,973,1545,1545,1493,960,1350,1545,453};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)()
				.. tostring(body):sub(1, 120))
		end
		task.wait(1)
	end

	-- 2. aus der lokalen Kopie
	local okFile, body = pcall(function()
		if isfile and isfile(RAYFIELD_CACHE) and readfile then
			return readfile(RAYFIELD_CACHE)
		end
		return nil
	end)
	if okFile and type(body) == (function()
        local a={1532,1545,1519,1402,1467,1376};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)() and #body > 2000 then
		print((function()
        local a={1220,895,1402,1376,973,1558,1311,1246,453,1051,1350,1545,1623,453,1376,1402,1467,1376,453,1467,1402,1324,1389,1545,609,453,1467,1350,1389,1454,1350,453,1337,1402,1350,453,1441,1480,1428,1298,1441,1350,453,1012,1480,1493,1402,1350};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)())
		local result = runRayfield(body, (function()
        local a={1441,1480,1428,1298,1441,1350,453,1012,1480,1493,1402,1350};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)(), problems)
		if result then
			return result
		end
	else
		table.insert(problems, (function()
        local a={1428,1350,1402,1467,1350,453,1441,1480,1428,1298,1441,1350,453,1012,1480,1493,1402,1350,453,1571,1480,1519,1389,1298,1467,1337,1350,1467};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)())
	end

	return nil, table.concat(problems, (function()
        local a={453,1649,453};
        local b='';
        for i=1,#a do 
            b=b..string.char((a[i]-37)/13);
        end;
        return b;
    end)())
end

