-- Gleitet zum Ziel statt zu blinken, und schaut es dabei an.
function Util.glide(position, speed)
	local root = Util.root()
	if not root then
		return false
	end

	local from = root.Position
	local distance = (position - from).Magnitude
	if distance < 1 then
		return true
	end

	local duration = math.clamp(distance / math.max(speed or 140, 10), 0.05, 2)
	local start = os.clock()

	while true do
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 then
			break
		end
		local current = Util.root()
		if not current then
			return false
		end
		local point = from:Lerp(position, alpha)
		local okCf = pcall(function()
			current.CFrame = CFrame.new(point, position)
		end)
		if not okCf then
			current.CFrame = CFrame.new(point)
		end
		task.wait(0.03)
	end

	local final = Util.root()
	if final then
		pcall(function()
			final.CFrame = CFrame.new(position, position + (position - from).Unit)
		end)
	end
	return true
end

--[[ ==========================================================================

	  M A I L B O X

	  Schritt 1  Mailbox-Fenster finden   -> Mailbox.frames()
	  Schritt 2  Felder fuellen           -> Mailbox.prepare()
	  Schritt 3  Pets filtern             -> Mailbox.collect()
	  Schritt 4  Pets anklicken + senden  -> Mailbox.send()

	  Jeder Schritt schreibt in die Konsole UND als Roblox-Meldung, wenn er
	  abbricht. Du siehst also immer, wo es haengt.

   ========================================================================== ]]

