local loops = {}
local loopToggles = {}
local masterToggle

local function defineLoop(name, def)
	local loop = {
		name    = name,
		def     = def,
		running = false,
		token   = 0,
		ticks   = 0,
	}
	loop.stop = function()
		loop.running = false
		local toggle = loopToggles[name]
		if toggle then
			pcall(function()
				toggle:Set(false)
			end)
		end
	end
	loops[name] = loop
	return loop
end

local function startLoop(name)
	local loop = loops[name]
	if not loop or loop.running then
		return
	end

	loop.running = true
	loop.ticks   = 0
	loop.token  += 1
	local token  = loop.token

